/* Simplified DOMPurify for Offline Use */
(function(global){
  var DOMPurify = {
    sanitize: function(html, config) {
      if (!html) return '';
      // Basic XSS protection - remove script tags and event handlers
      var clean = html;
      // Remove script tags
      clean = clean.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
      // Remove event handlers
      clean = clean.replace(/\s*on\w+\s*=\s*["'][^"']*["']/gi, '');
      clean = clean.replace(/\s*on\w+\s*=\s*[^\s>]+/gi, '');
      // Remove javascript: URLs
      clean = clean.replace(/href\s*=\s*["']javascript:[^"']*["']/gi, 'href="#"');
      clean = clean.replace(/src\s*=\s*["']javascript:[^"']*["']/gi, 'src=""');
      // Remove data: URLs in src (potential XSS)
      clean = clean.replace(/src\s*=\s*["']data:text\/html[^"']*["']/gi, 'src=""');
      return clean;
    }
  };
  global.DOMPurify = DOMPurify;
})(typeof window !== 'undefined' ? window : this);
